// Obtenemos todos los contenedores como array real
const containers = $input.all().map(i => i.json);

// Total contenedores
const total = containers.length;

// Contenedores running
const running = containers.filter(c => c.State === 'running').length;

// Contenedores stopped
const stopped = containers.filter(c => c.State !== 'running');
const stoppedNames = stopped.map(c =>
  (c.Names?.[0] || c.Id || 'unknown').replace('/', '')
);

// Contenedores healthy
const healthy = containers.filter(c =>
  (c.Status || '').includes('(healthy)')
).length;

// Contenedores unhealthy
const unhealthy = containers.filter(c =>
  (c.Status || '').includes('(unhealthy)')
).length;

// Devolvemos resumen final
return [{
  json: {
    docker_total: total,
    docker_running: running,
    docker_stopped_count: stopped.length,
    docker_stopped_names: stoppedNames,
    docker_healthy: healthy,
    docker_unhealthy: unhealthy
  }
}];

// El texto del scan viene en el campo "data"
const text = $json.data || "";

// Buscamos líneas que empiecen por "Nmap scan report for"
const reports = text
  .split('\n')
  .filter(l => l.startsWith("Nmap scan report for "));

const count = reports.length;

// Sacamos 3 ejemplos
const examples = reports
  .slice(0, 3)
  .map(l => l.replace("Nmap scan report for ", "").trim());

return [{
  json: {
    scan_count: count,
    scan_examples: examples
  }
}];

// Counters - Read & Reset
const staticData = $getWorkflowStaticData('global');

// Valores actuales (si no existen, poner 0 o guión)
const fail2ban_bans_today = staticData.fail2ban_bans_today ?? 0;
const fail2ban_last_ip = staticData.fail2ban_last_ip ?? '—';
const kuma_down_today = staticData.kuma_down_today ?? 0;
const kuma_last_service = staticData.kuma_last_service ?? '—';

const today = new Date().toISOString().slice(0, 10);

// Reset para el siguiente día
staticData.fail2ban_bans_today = 0;
staticData.fail2ban_last_ip = '—';
staticData.kuma_down_today = 0;
staticData.kuma_last_service = '—';
staticData.last_daily_report_date = today;

return [
  {
    json: {
      report_date: today,
      fail2ban_bans_today,
      fail2ban_last_ip,
      kuma_down_today,
      kuma_last_service,
    },
  },
];
